const st = window.__ensemble;
for (let i = 0; i < 10; i++) {
  if (st.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'onboarded: ' + st.getState().settings.onboarded

const s = window.__ensemble.getState(); const id = window.__c["goal"];
const rows = Object.entries(s.items).filter(([k]) => k.startsWith(id + ':')).map(([k, v]) => k.split(':')[1] + ': ' + v.filter(i => i.kind === 'turn').map(t => t.status + '/' + (t.steps || 0) + 's/' + Math.round(t.durationMs / 100) / 10 + 's').join(' '));
const blocks = [...document.querySelectorAll('[data-evidence]')].map(b => b.textContent.replace(/\s+/g, ' ').trim().slice(0, 200));
const goal = s.chats.find(c => c.id === id)?.goal;
return "goal" + ' | goal ' + (goal ? goal.status + ' r' + goal.round : '-') + ' | turns: ' + rows.join(' ; ') + ' | blocks: ' + JSON.stringify(blocks)

