await new Promise(r => setTimeout(r, 400));
let b = [...document.querySelectorAll('[data-evidence] > button')].pop();
if (!b) { const bs = [...document.querySelectorAll('button')].filter(x => /^\s*Evidence\s*$/.test(x.textContent || '')); const last = bs[bs.length - 1]; if (last) { last.click(); await new Promise(r => setTimeout(r, 900)); b = [...document.querySelectorAll('[data-evidence] > button')].pop() } }
if (!b) return 'no evidence block';
if (b.getAttribute('aria-expanded') !== 'true') b.click();
await new Promise(r => setTimeout(r, 500));
const box = b.parentElement;
let sc = box.parentElement; while (sc && !(sc.scrollHeight > sc.clientHeight + 4 && /auto|scroll/.test(getComputedStyle(sc).overflowY))) sc = sc.parentElement;
if (sc) sc.scrollTop += box.getBoundingClientRect().top - sc.getBoundingClientRect().top - 140;
await new Promise(r => setTimeout(r, 300));
return 'open: ' + box.textContent.replace(/\s+/g, ' ').trim().slice(0, 700)

